/* HEXA BATTLEGROUNDS setup — PART 28 OF 30. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-movie-0', 'movie', 'battle', 'Emoji Cinema Duel', 'movies', 1, array['duel_pistol']::text[], 'Duel! Name all three films before the other squad does.', '{"scout":{"title":"Film 1","body":"🎈 🏠 👴\n\n(2 letters · starts with U)","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🦇 🌃 🃏\n\n(3 words: 3 + 4 + 6 · starts with T)","mono":false,"big":true},"intel":{"title":"Film 3","body":"🔥 💧 🤝\n\n(3 letters · starts with R)","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["UP"]},{"label":"Film 2 (Decoder)","accept":["THEDARKKNIGHT","DARKKNIGHT","BATMAN"]},{"label":"Film 3 (Intel)","accept":["RRR"]}]'::jsonb, false, 3, 90, 'Say the emoji out loud. Answers start with: UP…, TH…, RR…', 'UP: balloons lift a house | THE DARK KNIGHT: bat, night, joker | RRR: fire and water, friendship', null, 25, 'published'), ('battle-movie-1', 'movie', 'battle', 'Emoji Cinema Duel', 'movies', 1, array['duel_pistol']::text[], 'Duel! Name all three films before the other squad does.', '{"scout":{"title":"Film 1","body":"🏴‍☠️ 🌴 💀\n\n(4 words: 7 + 2 + 3 + 9 · starts with P)","mono":false,"big":true},"decoder":{"title":"Film 2","body":"👻 🚫 📞\n\n(12 letters · starts with G)","mono":false,"big":true},"intel":{"title":"Film 3","body":"🌀 💤 🏙️\n\n(9 letters · starts with I)","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["PIRATESOFTHECARIBBEAN","PIRATES"]},{"label":"Film 2 (Decoder)","accept":["GHOSTBUSTERS"]},{"label":"Film 3 (Intel)","accept":["INCEPTION"]}]'::jsonb, false, 3, 90, 'Say the emoji out loud. Answers start with: PI…, GH…, IN…', 'PIRATES OF THE CARIBBEAN: pirates, islands | GHOSTBUSTERS: who you gonna call | INCEPTION: dreams inside dreams', null, 25, 'published'), ('mission-tech-0', 'techquick', 'mission', 'Tech Quick-Fire', 'tech', 1, array['any','stg','testing','helpdesk','learning','phase2','hexavarsity']::text[], 'Three quick tech questions, one per teammate. One word each.', '{"scout":{"title":"Question 1","body":"Which company''s logo is a bitten fruit?\n\n(5 letters · starts with A)","mono":false,"big":false},"decoder":{"title":"Question 2","body":"Ctrl + Z does what?\n\n(4 letters · starts with U)","mono":false,"big":false},"intel":{"title":"Question 3","body":"Smallest unit of data — a single 0 or 1.\n\n(3 letters · starts with B)","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["APPLE"]},{"label":"Question 2 (Decoder)","accept":["UNDO"]},{"label":"Question 3 (Intel)","accept":["BIT"]}]'::jsonb, false, 3, 200, 'Every answer is one short word. Answers start with: AP…, UN…, BI…', 'APPLE: Apple | UNDO: Undo | BIT: a bit', null, 25, 'published'), ('mission-tech-1', 'techquick', 'mission', 'Tech Quick-Fire', 'tech', 1, array['any','stg','testing','helpdesk','learning','phase2','hexavarsity']::text[], 'Three quick tech questions, one per teammate. One word each.', '{"scout":{"title":"Question 1","body":"Google''s mobile operating system.\n\n(7 letters · starts with A)","mono":false,"big":false},"decoder":{"title":"Question 2","body":"8 bits make one ___.\n\n(4 letters · starts with B)","mono":false,"big":false},"intel":{"title":"Question 3","body":"HTML = HyperText ___ Language.\n\n(6 letters · starts with M)","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["ANDROID"]},{"label":"Question 2 (Decoder)","accept":["BYTE"]},{"label":"Question 3 (Intel)","accept":["MARKUP"]}]'::jsonb, false, 3, 200, 'Every answer is one short word. Answers start with: AN…, BY…, MA…', 'ANDROID: Android | BYTE: a byte | MARKUP: Markup', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-tech-2', 'techquick', 'mission', 'Tech Quick-Fire', 'tech', 1, array['any','stg','testing','helpdesk','learning','phase2','hexavarsity']::text[], 'Three quick tech questions, one per teammate. One word each.', '{"scout":{"title":"Question 1","body":"Programming language with a coffee-cup logo.\n\n(4 letters · starts with J)","mono":false,"big":false},"decoder":{"title":"Question 2","body":"Language named after a British comedy group, not a snake.\n\n(6 letters · starts with P)","mono":false,"big":false},"intel":{"title":"Question 3","body":"Ctrl + C copies. Ctrl + ___ pastes.\n\n(1 letters · starts with V)","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["JAVA"]},{"label":"Question 2 (Decoder)","accept":["PYTHON"]},{"label":"Question 3 (Intel)","accept":["V","CTRLV"]}]'::jsonb, false, 3, 200, 'Every answer is one short word. Answers start with: JA…, PY…, V…', 'JAVA: Java | PYTHON: Python (Monty Python) | V: Ctrl + V', null, 25, 'published'), ('mission-tech-3', 'techquick', 'mission', 'Tech Quick-Fire', 'tech', 1, array['any','stg','testing','helpdesk','learning','phase2','hexavarsity']::text[], 'Three quick tech questions, one per teammate. One word each.', '{"scout":{"title":"Question 1","body":"Number system that uses only 0 and 1.\n\n(6 letters · starts with B)","mono":false,"big":false},"decoder":{"title":"Question 2","body":"Company that owns WhatsApp and Instagram.\n\n(4 letters · starts with M)","mono":false,"big":false},"intel":{"title":"Question 3","body":"Mbps = megabits per ___.\n\n(6 letters · starts with S)","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["BINARY","BASE2"]},{"label":"Question 2 (Decoder)","accept":["META","FACEBOOK"]},{"label":"Question 3 (Intel)","accept":["SECOND","SEC"]}]'::jsonb, false, 3, 200, 'Every answer is one short word. Answers start with: BI…, ME…, SE…', 'BINARY: binary | META: Meta | SECOND: second', null, 25, 'published'), ('battle-tech-0', 'techquick', 'battle', 'Tech Quick-Fire Duel', 'tech', 1, array['duel_smg']::text[], 'Rapid fire! Three one-word tech answers — fastest squad wins.', '{"scout":{"title":"Question 1","body":"Unwanted bulk email is called ___.\n\n(4 letters · starts with S)","mono":false,"big":false},"decoder":{"title":"Question 2","body":"Key you press to refresh most browsers.\n\n(2 letters · starts with F)","mono":false,"big":false},"intel":{"title":"Question 3","body":"What does the \"I\" in AI stand for?\n\n(12 letters · starts with I)","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["SPAM"]},{"label":"Question 2 (Decoder)","accept":["F5"]},{"label":"Question 3 (Intel)","accept":["INTELLIGENCE"]}]'::jsonb, false, 3, 90, 'One word each. Answers start with: SP…, F5…, IN…', 'SPAM: spam | F5: F5 | INTELLIGENCE: Intelligence', null, 25, 'published'), ('battle-tech-1', 'techquick', 'battle', 'Tech Quick-Fire Duel', 'tech', 1, array['duel_smg']::text[], 'Rapid fire! Three one-word tech answers — fastest squad wins.', '{"scout":{"title":"Question 1","body":"Fake login emails that steal passwords are called ___.\n\n(8 letters · starts with P)","mono":false,"big":false},"decoder":{"title":"Question 2","body":"A problem in code is nicknamed a ___.\n\n(3 letters · starts with B)","mono":false,"big":false},"intel":{"title":"Question 3","body":"What does \"www\" stand for? World Wide ___\n\n(3 letters · starts with W)","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["PHISHING"]},{"label":"Question 2 (Decoder)","accept":["BUG"]},{"label":"Question 3 (Intel)","accept":["WEB"]}]'::jsonb, false, 3, 90, 'One word each. Answers start with: PH…, BU…, WE…', 'PHISHING: phishing | BUG: bug | WEB: Web', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-sudoku-0', 'sudoku', 'mission', 'Mini Sudoku Vault', 'logic', 2, array['any','learning','office','glass','observation','phase2']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"· 2 · 4\n1 · 3 ·\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[0,2,0,4],[1,0,3,0],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n· 1 · ·\n2 3 4 ·","mono":true,"grid":{"rows":[null,null,[0,1,0,0],[2,3,4,0]]}},"intel":{"title":"Code cells","body":"A = row 1, column 1\nB = row 4, column 4\nC = row 3, column 4\nD = row 2, column 4\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["3132"]}]'::jsonb, false, 3, 240, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 3214 / 1432 / 4123 / 2341 → 3132', null, 25, 'published'), ('mission-sudoku-1', 'sudoku', 'mission', 'Mini Sudoku Vault', 'logic', 2, array['any','learning','office','glass','observation','phase2']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"· 3 4 1\n· · · ·\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[0,3,4,1],[0,0,0,0],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n· 1 · 3\n3 2 1 ·","mono":true,"grid":{"rows":[null,null,[0,1,0,3],[3,2,1,0]]}},"intel":{"title":"Code cells","body":"A = row 2, column 2\nB = row 1, column 1\nC = row 4, column 4\nD = row 3, column 1\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["4244"]}]'::jsonb, false, 3, 240, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 2341 / 1432 / 4123 / 3214 → 4244', null, 25, 'published'), ('mission-sudoku-2', 'sudoku', 'mission', 'Mini Sudoku Vault', 'logic', 2, array['any','learning','office','glass','observation','phase2']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"· 1 · ·\n4 2 · 3\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[0,1,0,0],[4,2,0,3],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n· 3 4 2\n2 · · ·","mono":true,"grid":{"rows":[null,null,[0,3,4,2],[2,0,0,0]]}},"intel":{"title":"Code cells","body":"A = row 4, column 3\nB = row 3, column 1\nC = row 2, column 3\nD = row 1, column 1\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["3113"]}]'::jsonb, false, 3, 240, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 3124 / 4213 / 1342 / 2431 → 3113', null, 25, 'published'), ('mission-sudoku-3', 'sudoku', 'mission', 'Mini Sudoku Vault', 'logic', 2, array['any','learning','office','glass','observation','phase2']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"· 3 4 ·\n1 4 · 2\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[0,3,4,0],[1,4,0,2],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n4 · · ·\n3 · 1 ·","mono":true,"grid":{"rows":[null,null,[4,0,0,0],[3,0,1,0]]}},"intel":{"title":"Code cells","body":"A = row 3, column 2\nB = row 4, column 2\nC = row 1, column 1\nD = row 2, column 3\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["1223"]}]'::jsonb, false, 3, 240, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 2341 / 1432 / 4123 / 3214 → 1223', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.p